CREATE OR REPLACE FUNCTION public.guard_initial_admin_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN PERFORM pg_advisory_xact_lock(420231); IF lower(NEW.email) <> 'rblisboa2022@gmail.com' OR NEW.email IS NULL THEN RAISE EXCEPTION 'Cadastro não autorizado'; END IF; IF EXISTS (SELECT 1 FROM auth.users WHERE lower(email) = 'rblisboa2022@gmail.com') OR EXISTS (SELECT 1 FROM public.user_roles WHERE role = 'admin') THEN RAISE EXCEPTION 'Conta já existente. Entre ou recupere sua senha.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_initial_admin_signup BEFORE INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.guard_initial_admin_signup();
CREATE OR REPLACE FUNCTION public.authorize_confirmed_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF lower(NEW.email) = 'rblisboa2022@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN PERFORM pg_advisory_xact_lock(420231); INSERT INTO public.user_roles(user_id,role) VALUES (NEW.id,'admin') ON CONFLICT (user_id,role) DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER authorize_confirmed_owner AFTER INSERT OR UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.authorize_confirmed_owner();
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles r JOIN auth.users u ON u.id=r.user_id WHERE r.user_id=_user_id AND r.role=_role AND lower(u.email)='rblisboa2022@gmail.com' AND u.email_confirmed_at IS NOT NULL) $$;
CREATE OR REPLACE FUNCTION public.is_staff(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.has_role(_user_id,'admin') $$;
CREATE OR REPLACE FUNCTION public.admin_exists() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM auth.users WHERE lower(email)='rblisboa2022@gmail.com') OR EXISTS (SELECT 1 FROM public.user_roles WHERE role='admin') $$;
CREATE OR REPLACE FUNCTION public.claim_first_admin() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN PERFORM pg_advisory_xact_lock(420231); IF auth.uid() IS NULL OR NOT EXISTS (SELECT 1 FROM auth.users WHERE id=auth.uid() AND lower(email)='rblisboa2022@gmail.com' AND email_confirmed_at IS NOT NULL) THEN RETURN false; END IF; IF EXISTS (SELECT 1 FROM public.user_roles WHERE role='admin' AND user_id<>auth.uid()) THEN RETURN false; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'admin') ON CONFLICT(user_id,role) DO NOTHING; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.guard_initial_admin_signup(), public.authorize_confirmed_owner() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.admin_exists() TO anon, authenticated;
REVOKE ALL ON FUNCTION public.claim_first_admin() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.claim_first_admin() TO authenticated;
CREATE TABLE public.submission_rate_limits (bucket_key text PRIMARY KEY, window_start timestamptz NOT NULL DEFAULT now(), attempts integer NOT NULL DEFAULT 1);
GRANT ALL ON public.submission_rate_limits TO service_role;
ALTER TABLE public.submission_rate_limits ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.consume_submission_limit(_bucket text, _max integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE hits integer; BEGIN INSERT INTO public.submission_rate_limits(bucket_key) VALUES(_bucket) ON CONFLICT(bucket_key) DO UPDATE SET attempts=CASE WHEN submission_rate_limits.window_start < now()-interval '1 hour' THEN 1 ELSE submission_rate_limits.attempts+1 END, window_start=CASE WHEN submission_rate_limits.window_start < now()-interval '1 hour' THEN now() ELSE submission_rate_limits.window_start END RETURNING attempts INTO hits; RETURN hits<=_max; END $$;
REVOKE ALL ON FUNCTION public.consume_submission_limit(text,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.consume_submission_limit(text,integer) TO service_role;